content.content:
     * needs approval, whatever its size, as does every draft that would take its client over its credit limit
     * (overCreditLimit). A draft whose grand total is more than one and a half times the approval limit, or
     * of a HIGH payment risk client, needs {@link #approvalsRequired two approvals} of that same total. So does
     * a draft that is a possible duplicate of an invoice recently sent to its client (possibleDuplicate). Every
     * draft of a client with an invoice still overdue after its second reminder (remindersIgnored) needs approval.
     */
    public Approval approval(BigDecimal taxRate, LocalDate today, boolean highRisk, boolean overCreditLimit,
            boolean possibleDuplicate, boolean remindersIgnored) {
        if (isCreditNote()) {
            return Approval.NOT_NEEDED;
        }
        if (!isDraft()) {
            return approvedTotal == null ? Approval.NOT_NEEDED : Approval.APPROVED;
        }
        BigDecimal limit = approvalLimit();
        BigDecimal total = approvalTotal(taxRate);
        if (!highRisk && !overCreditLimit && !possibleDuplicate && !remindersIgnored && !discountIsLarge() && (limit == null || total.compareTo(limit) <= 0)) {
            return Approval.NOT_NEEDED;
        }
        return approvalsAt(total, today) < approvalsRequired(taxRate) ? Approval.NEEDS_APPROVAL : Approval.APPROVED;
    }

    /**
     * The approvals a draft needs: two when its client is a HIGH payment risk or its grand total is more than
     * one and a half times the approval limit, else one.
     */
    public int approvalsRequired(BigDecimal taxRate) {
        if (highRiskClient) {
            return 2;
        }
        BigDecimal limit = approvalLimit();
        return limit != null && approvalTotal(taxRate).compareTo(limit.multiply(new BigDecimal("1.5"))) > 0 ? 2 : 1;
    }

    /**
     * The approvals that still stand for the grand total as of today: those given at exactly that total,
     * unless more than {@link #approvalDays} days have passed since the last of them; else none.
     */
    private int approvalsAt(BigDecimal total, LocalDate today) {
        if (approvedTotal == null || total.compareTo(approvedTotal) != 0) {
            return 0;
        }
        boolean lapsed = approvedOn != null && today.isAfter(afterDays(approvedOn, approvalDays()));
        return lapsed ? 0 : approvals;
    }

    /** The approvals the invoice still needs before it is sent, given its approval: none unless it needs approval. */
    public int approvalsNeeded(Approval approval, BigDecimal taxRate, LocalDate today) {
        if (approval != Approval.NEEDS_APPROVAL) {
            return 0;
        }
        return Math.max(1, approvalsRequired(taxRate) - approvalsAt(approvalTotal(taxRate), today));
    }

    /** The approvals that stand for the grand total as of today (see {@link #approvalsNeeded}). */
    public int approvalsGiven(BigDecimal taxRate, LocalDate today) {
        return approvalsAt(approvalTotal(taxRate), today);
    }

    public int getApprovals() {
        return approvals;
    }

    public BigDecimal getApprovedTotal() {
        return approvedTotal;
    }

    public LocalDate getApprovedOn() {
        return approvedOn;
    }

    /**
     * Approves the invoice at the grand total on the day: one more approval when the approvals given still
     * stand for that total, else its first.
     */
    public void approve(BigDecimal total, LocalDate on) {
        this.approvals = approvalsAt(total, on) + 1;
        this.approvedTotal = total;
        this.approvedOn = on;
    }

